-- =============================================================================
-- Studuel — Migration 233 : SVT Tle (spécialité) — LES 22 FICHES DU PROGRAMME OFFICIEL
--
-- ⚠️ FICHIER GÉNÉRÉ — ne pas éditer à la main.
--    Source : scripts/contenu/*.mjs
--    Regénérer : node scripts/seed-contenu.mjs --num 233 --modules svt-tle
--
-- CONSTAT MESURÉ (lecture des migrations 008 et 142, 05/08/2026) : la
-- spécialité SVT de terminale n'avait que 5 chapitres, taillés dans un découpage
-- maison (« Génétique et évolution », « Le temps et les roches », « Les climats
-- de la Terre », « Comportement et stress », « De la plante sauvage à la plante
-- cultivée ») qui résumait chaque chapitre du BO en UNE fiche. Deux chapitres
-- entiers du programme n'avaient aucune entrée : « Comportements, mouvement et
-- système nerveux » et « Produire le mouvement : contraction musculaire et
-- apport d'énergie ». Un élève qui révisait le réflexe myotatique, le sarcomère,
-- la régulation de la glycémie, la chronologie absolue, la photosynthèse ou les
-- paramètres de Milankovitch ne trouvait rien. Cette migration installe les 22
-- fiches du programme officiel, dans l'ordre des 7 chapitres du BO, et retire
-- les 5 fiches de synthèse qu'elles recouvrent entièrement.
-- ⚠️ CE QUI EST PERDU AU PASSAGE : les 5 leçons « Exercices types » posées par
-- la migration 142 (2 exercices type bac corrigés par chapitre) partent avec
-- leurs chapitres. Elles étaient adossées au découpage composite ; les réécrire
-- fiche par fiche est un chantier à part.
--
-- Cette migration apporte : 22 chapitres, 22 leçons,
-- 22 quiz et 176 questions, sur 1 matière.
--
-- CHOIX ASSUMÉS :
--  · tous les quiz sont `is_free = true`. Aucun compte ne peut aujourd’hui
--    passer `tier1` (aucun paiement n’existe), donc un quiz payant serait un
--    quiz INVISIBLE pour 100 % des élèves — le contraire du but ;
--  · chaque cours porte des sections `##`, ce qui rend sa carte mentale
--    dérivable (cf. lib/mind-map-auto) : aucune tuile ne promet dans le vide.
--
-- Idempotent : les UUID sont dérivés du contenu (SHA-1), donc stables ; les
-- INSERT sont tous gardés par ON CONFLICT DO NOTHING. Rejouable sans risque.
--
-- PRÉREQUIS : 002, 008, 191, 193 exécutées (les matières doivent exister).
-- À exécuter dans : Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

-- 0. Ménage ----------------------------------------------------------------
-- [svt] La file « À revoir » d'abord : review_items.item_id n'a PAS de clé
-- [svt] étrangère (il pointe soit une question, soit une carte). Rien ne casse si on
-- [svt] l'oublie — le lecteur écarte déjà un contenu disparu — mais le compteur
-- [svt] « X à revoir » continuerait de compter des questions qui n'existent plus.
DELETE FROM public.review_items ri
 USING public.quiz_questions qq, public.quizzes qz, public.lessons l,
       public.chapters c, public.subjects s
 WHERE ri.item_kind = 'question'
   AND ri.item_id = qq.id
   AND qq.quiz_id = qz.id
   AND qz.lesson_id = l.id
   AND l.chapter_id = c.id
   AND c.subject_id = s.id
   AND s.slug = 'svt'
   AND c.level = 'Tle'
   AND l.title IN ('L''essentiel du cours', 'Exercices types');

-- [svt] Les quiz ensuite : quizzes.lesson_id est ON DELETE SET NULL, donc
-- [svt] supprimer le chapitre laisserait derrière lui des quiz orphelins, rattachés à
-- [svt] aucune leçon mais toujours servis par le moteur de révision.
DELETE FROM public.quizzes q
 USING public.lessons l, public.chapters c, public.subjects s
 WHERE q.lesson_id = l.id
   AND l.chapter_id = c.id
   AND c.subject_id = s.id
   AND s.slug = 'svt'
   AND c.level = 'Tle'
   AND l.title IN ('L''essentiel du cours', 'Exercices types');

-- [svt] Puis les chapitres : leçons, fiches de révision, supports, progression
-- [svt] et chapitres cochés partent en cascade (toutes les clés étrangères vers
-- [svt] chapters et lessons sont ON DELETE CASCADE).
DELETE FROM public.chapters c
 USING public.subjects s
 WHERE c.subject_id = s.id
   AND s.slug = 'svt'
   AND c.level = 'Tle'
   AND EXISTS (
     SELECT 1 FROM public.lessons l
      WHERE l.chapter_id = c.id
        AND l.title IN ('L''essentiel du cours', 'Exercices types')
   );

-- 1. Chapitres -------------------------------------------------------------
