-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('60efbd2c-c6b5-5fdc-a02f-2850f9eafeb4'::uuid, 'add67d35-1147-5985-9b99-9d760e245e10'::uuid, 'À quel moment du cycle cellulaire l’ADN est-il répliqué ?', 'mcq', '["En phase S","En phase G1","En phase G2","Pendant l’anaphase"]'::jsonb, 0, 'La phase S de l’interphase double chaque chromosome, qui passe à deux chromatides.', 1),
    ('c80c6db5-5838-5fde-868a-9aa62ffd75ce'::uuid, 'add67d35-1147-5985-9b99-9d760e245e10'::uuid, 'Que montre l’expérience de Meselson et Stahl ?', 'mcq', '["La réplication est semi-conservative","L’ADN est une protéine","La mitose précède la réplication","Les mutations sont dirigées"]'::jsonb, 0, 'Chaque molécule fille garde un brin ancien et gagne un brin neuf.', 2),
    ('31b61092-14f6-5875-ac20-6a5a3c10e048'::uuid, 'add67d35-1147-5985-9b99-9d760e245e10'::uuid, 'La mitose produit deux cellules génétiquement identiques.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est la définition même d’un clone cellulaire.', 3),
    ('138f4fa1-b43d-5481-bf12-cadeb542eeab'::uuid, 'add67d35-1147-5985-9b99-9d760e245e10'::uuid, 'Quel est l’ordre de grandeur du taux d’erreur APRÈS relecture et réparation ?', 'mcq', '["Une erreur sur 10⁹ nucléotides","Une erreur sur 100 nucléotides","Une erreur sur 10 nucléotides","Aucune erreur"]'::jsonb, 0, 'La polymérase se trompe une fois sur 10⁵, mais relecture et réparation corrigent l’essentiel.', 4),
    ('79d03584-8428-50f2-b1c6-9e5e51b2b530'::uuid, 'add67d35-1147-5985-9b99-9d760e245e10'::uuid, 'Une mutation somatique est transmise aux enfants de l’individu.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Seules les mutations des cellules germinales le sont ; la somatique reste dans le corps.', 5),
    ('639407dd-4cf7-59ea-939e-a23a5bd10e8a'::uuid, 'add67d35-1147-5985-9b99-9d760e245e10'::uuid, 'Comment se forme un clone de cellules cancéreuses ?', 'mcq', '["Par mutations somatiques touchant le contrôle du cycle cellulaire","Par méiose anormale","Par fécondation croisée","Par transfert horizontal de gènes"]'::jsonb, 0, 'La cellule mutée transmet la mutation à toute sa descendance, qui prolifère.', 6),
    ('8d1c9a9d-d4d0-51c4-8ad8-0ab0b612c000'::uuid, 'add67d35-1147-5985-9b99-9d760e245e10'::uuid, 'Quel mode de reproduction produit des individus génétiquement identiques au parent ?', 'mcq', '["La reproduction asexuée","La reproduction sexuée","L’hybridation","La polyploïdisation"]'::jsonb, 0, 'Bouturage, stolons, scissiparité, parthénogenèse : tous donnent des clones.', 7),
    ('c01da9bd-c5cb-561b-9cd6-980bfa48fed9'::uuid, 'add67d35-1147-5985-9b99-9d760e245e10'::uuid, 'Quel est le principal inconvénient de la reproduction asexuée ?', 'mcq', '["Elle ne crée aucune diversité génétique nouvelle","Elle est trop lente","Elle exige deux parents","Elle empêche la mitose"]'::jsonb, 0, 'Une population clonale est fragile face à un changement du milieu ou à un parasite.', 8),
    ('2173a86b-3efe-5533-a0a3-5d007ff26dbb'::uuid, '1f2f5914-ab9e-5f0d-8f18-ca9f18a3e901'::uuid, 'Combien de cellules haploïdes une méiose produit-elle à partir d’une cellule diploïde ?', 'mcq', '["Quatre","Deux","Une","Huit"]'::jsonb, 0, 'Deux divisions successives : la réductionnelle puis l’équationnelle.', 1),
    ('697cef67-4cf4-5a3e-8f01-9441e9df5bd8'::uuid, '1f2f5914-ab9e-5f0d-8f18-ca9f18a3e901'::uuid, 'Quel brassage a lieu à l’anaphase de la première division de méiose ?', 'mcq', '["Le brassage interchromosomique","Le brassage intrachromosomique","La fécondation","La réplication"]'::jsonb, 0, 'Chaque paire d’homologues se répartit indépendamment des autres.', 2),
    ('6e7838a6-810f-50e6-86db-b8ec10ed32ad'::uuid, '1f2f5914-ab9e-5f0d-8f18-ca9f18a3e901'::uuid, 'Le brassage interchromosomique donne 2²³ combinaisons chez l’espèce humaine.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Soit plus de 8 millions de gamètes différents possibles.', 3),
    ('5991f81e-fa9a-5318-8164-1dbab5c07796'::uuid, '1f2f5914-ab9e-5f0d-8f18-ca9f18a3e901'::uuid, 'Où et quand se produisent les crossing-over ?', 'mcq', '["En prophase de la première division de méiose","En métaphase de mitose","Pendant la fécondation","En phase G1"]'::jsonb, 0, 'Les chromatides d’homologues appariés échangent alors des portions.', 4),
    ('6b901187-0ceb-5409-a49b-83eae6a2c2e2'::uuid, '1f2f5914-ab9e-5f0d-8f18-ca9f18a3e901'::uuid, 'Pour deux gènes LIÉS, un croisement-test donne…', 'mcq', '["Des phénotypes recombinés minoritaires","Quatre phénotypes équiprobables","Un seul phénotype","Aucun phénotype parental"]'::jsonb, 0, 'Les recombinés n’apparaissent que si un crossing-over a eu lieu entre les deux gènes.', 5),
    ('23883d4a-a751-5545-ac70-5c8de32ce30a'::uuid, '1f2f5914-ab9e-5f0d-8f18-ca9f18a3e901'::uuid, 'Quelle anomalie de méiose est à l’origine de la trisomie 21 ?', 'mcq', '["Une non-disjonction chromosomique","Un crossing-over inégal","Une duplication génique","Une mutation ponctuelle"]'::jsonb, 0, 'La paire 21 ne se sépare pas : le gamète porte un chromosome en trop.', 6),
    ('da82764f-cbdc-5ef0-aa16-f82fee499287'::uuid, '1f2f5914-ab9e-5f0d-8f18-ca9f18a3e901'::uuid, 'Un crossing-over inégal peut créer une duplication de gène.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’origine des familles multigéniques, comme celle des globines.', 7),
    ('5754c030-60e0-5f03-81cc-4a081d49a13e'::uuid, '1f2f5914-ab9e-5f0d-8f18-ca9f18a3e901'::uuid, 'Quel est le troisième brassage du cycle sexué, après les deux de la méiose ?', 'mcq', '["La fécondation, qui réunit deux gamètes au hasard","La mitose de la cellule œuf","La réplication de l’ADN","La méiose de la génération suivante"]'::jsonb, 0, 'Elle multiplie les combinaisons déjà produites par la méiose.', 8),
    ('4a281a6f-1c60-552d-83c7-df068fb0569a'::uuid, 'e0121fae-5593-5629-a454-6390ca64894d'::uuid, 'Qu’est-ce qu’un transfert horizontal de gènes ?', 'mcq', '["Le passage d’un gène d’un organisme à un autre sans reproduction","La transmission d’un gène du parent à l’enfant","Un crossing-over","Une duplication génique"]'::jsonb, 0, 'Il est très fréquent chez les bactéries : conjugaison, transformation, transduction.', 1),
    ('fa4fe82f-b62b-56d3-81c3-803aa9b04f5b'::uuid, 'e0121fae-5593-5629-a454-6390ca64894d'::uuid, 'Le gène de la syncytine, indispensable au placenta, est d’origine virale.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est un exemple de transfert horizontal ancien chez les mammifères.', 2),
    ('5051637c-cfda-54ed-b672-aa3b91f84530'::uuid, 'e0121fae-5593-5629-a454-6390ca64894d'::uuid, 'Comment une hybridation peut-elle donner une espèce nouvelle et fertile ?', 'mcq', '["Par polyploïdisation, qui rend la méiose de nouveau possible","Par mitose accélérée","Par sélection naturelle seule","Par dérive génétique"]'::jsonb, 0, 'Le doublement du stock chromosomique restaure l’appariement des homologues : c’est l’histoire du blé tendre.', 3),
    ('6ba0a869-ff18-5525-bd43-81f11b03cc74'::uuid, 'e0121fae-5593-5629-a454-6390ca64894d'::uuid, 'Quelle association permet à une légumineuse de profiter du diazote de l’air ?', 'mcq', '["Les nodosités à bactéries Rhizobium","Les mycorhizes","Les lichens","Le microbiote intestinal"]'::jsonb, 0, 'Les Rhizobium fixent le N₂ atmosphérique et le cèdent à la plante.', 4),
    ('79122fd9-1601-59a1-bfef-2816e276f023'::uuid, 'e0121fae-5593-5629-a454-6390ca64894d'::uuid, 'Un lichen associe un champignon et une algue ou une cyanobactérie.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Chaque partenaire y gagne : le phénotype de l’association dépasse la somme des deux.', 5),
    ('17380001-115e-5c2b-812a-49a0f9b7fc53'::uuid, 'e0121fae-5593-5629-a454-6390ca64894d'::uuid, 'Que montrent les techniques de pêche aux termites des chimpanzés ?', 'mcq', '["Une transmission culturelle, indépendante du génome","Une mutation avantageuse","Un transfert horizontal de gènes","Une polyploïdisation"]'::jsonb, 0, 'Les techniques varient d’un groupe à l’autre : ce sont des traditions apprises.', 6),
    ('3f6e2412-81b7-56c2-9a31-33ab436faaa8'::uuid, 'e0121fae-5593-5629-a454-6390ca64894d'::uuid, 'La diffusion du perçage des capsules de lait chez les mésanges est un exemple de…', 'mcq', '["Diversification non génétique par apprentissage","Sélection artificielle","Symbiose","Dérive génétique"]'::jsonb, 0, 'Le comportement s’est propagé par imitation, pas par hérédité.', 7),
    ('c7f94de2-6b95-5ba7-9994-2324457233a5'::uuid, 'e0121fae-5593-5629-a454-6390ca64894d'::uuid, 'Une symbiose modifie le génome des deux partenaires.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle modifie leurs capacités, pas leur ADN : les génomes restent distincts.', 8),
    ('fa150c81-b337-5d93-ae98-bb94486b1237'::uuid, '42d5b297-8efb-5d91-84b0-cb517f6d23e0'::uuid, 'À quoi sert le modèle de Hardy-Weinberg ?', 'mcq', '["De référence nulle : tout écart signale une force évolutive","À prouver que les espèces ne changent pas","À dater les roches","À calculer le nombre de gamètes"]'::jsonb, 0, 'Il décrit une population idéale où les fréquences alléliques resteraient stables.', 1),
    ('ad48c3ee-a54f-5826-b1a3-e49fe02ce4e5'::uuid, '42d5b297-8efb-5d91-84b0-cb517f6d23e0'::uuid, 'Dans une population conforme à Hardy-Weinberg, la fréquence des hétérozygotes vaut…', 'mcq', '["2pq","p²","q²","p + q"]'::jsonb, 0, 'Avec p² pour un homozygote et q² pour l’autre, la somme faisant 1.', 2),
    ('2aadf598-e4ce-576e-b827-1a7a427c9b16'::uuid, '42d5b297-8efb-5d91-84b0-cb517f6d23e0'::uuid, 'L’antibiotique crée la mutation de résistance chez la bactérie.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il ne fait que SÉLECTIONNER les bactéries qui la portaient déjà par hasard.', 3),
    ('976e66b7-ed66-55c8-a2d8-a0c860cfd957'::uuid, '42d5b297-8efb-5d91-84b0-cb517f6d23e0'::uuid, 'Qu’est-ce que la dérive génétique ?', 'mcq', '["Une variation au hasard des fréquences alléliques, marquée en petite population","Le tri des mieux adaptés","Un transfert horizontal de gènes","La migration des allèles entre espèces"]'::jsonb, 0, 'Elle peut fixer ou éliminer un allèle sans le moindre avantage sélectif.', 4),
    ('2dd4bccd-f3ee-57fe-a8a7-ef8d0f273abb'::uuid, '42d5b297-8efb-5d91-84b0-cb517f6d23e0'::uuid, 'Quel est le critère d’espèce le plus couramment retenu ?', 'mcq', '["L’interfécondité avec descendance fertile","La ressemblance de couleur","Le partage d’un même habitat","La taille du génome"]'::jsonb, 0, 'Il est cependant inapplicable aux fossiles et aux organismes asexués.', 5),
    ('37c2f0aa-9763-5758-ae87-20d1375945f6'::uuid, '42d5b297-8efb-5d91-84b0-cb517f6d23e0'::uuid, 'Que faut-il d’abord pour qu’une spéciation s’amorce ?', 'mcq', '["Un isolement reproducteur entre deux populations","Une mutation unique","Une crise biologique","Une polyploïdisation"]'::jsonb, 0, 'Sans échange de gènes, sélection et dérive font diverger les deux populations.', 6),
    ('5bb783df-3e0e-5d74-b458-20b24ec795e5'::uuid, '42d5b297-8efb-5d91-84b0-cb517f6d23e0'::uuid, 'La phalène du bouleau illustre la sélection naturelle par la pollution industrielle.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La forme sombre devient majoritaire sur les troncs noircis, puis régresse après dépollution.', 7),
    ('c8960bb0-495c-54ff-af16-7eafad103993'::uuid, '42d5b297-8efb-5d91-84b0-cb517f6d23e0'::uuid, 'Que se passe-t-il après une crise biologique majeure ?', 'mcq', '["Les groupes survivants se diversifient dans les niches libérées","La biodiversité reste figée","Toutes les espèces disparaissent","La dérive génétique cesse"]'::jsonb, 0, 'C’est ce qui suit la crise Crétacé-Paléogène pour les mammifères.', 8),
    ('55f53f45-cedb-58eb-bcd4-7fa70fa03512'::uuid, '116c8b51-0cd5-5df0-ab0c-d8577614ec1a'::uuid, 'Que dit le principe de superposition ?', 'mcq', '["Dans une série non déformée, une couche est plus récente que celle qu’elle recouvre","Un objet inclus est plus récent","Une faille est plus ancienne que les couches","Deux couches ont toujours le même âge"]'::jsonb, 0, 'La restriction « non déformée » est essentielle : une série peut être renversée.', 1),
    ('a6c3fb2c-0d7d-558e-807d-3a49c159a364'::uuid, '116c8b51-0cd5-5df0-ab0c-d8577614ec1a'::uuid, 'Une faille qui décale une couche est plus ancienne que cette couche.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le principe de recoupement dit l’inverse : ce qui recoupe est postérieur.', 2),
    ('625bd91d-6b94-5867-b6fc-c65752faed76'::uuid, '116c8b51-0cd5-5df0-ab0c-d8577614ec1a'::uuid, 'Un galet inclus dans un conglomérat est…', 'mcq', '["Plus ancien que le conglomérat","Plus récent que le conglomérat","Du même âge exactement","Indatable"]'::jsonb, 0, 'C’est le principe d’inclusion : l’objet inclus préexistait à la roche qui l’enferme.', 3),
    ('271c72c8-d159-51f2-8615-dab8e5940fae'::uuid, '116c8b51-0cd5-5df0-ab0c-d8577614ec1a'::uuid, 'Quelles qualités fait un bon fossile stratigraphique ?', 'mcq', '["Large répartition, courte durée d’existence, abondance","Grande taille et rareté","Longue durée d’existence","Répartition strictement locale"]'::jsonb, 0, 'Une espèce qui a duré 200 millions d’années ne découpe aucune tranche de temps.', 4),
    ('9204c65e-45b3-5bd3-9ab3-d23d58fc7c61'::uuid, '116c8b51-0cd5-5df0-ab0c-d8577614ec1a'::uuid, 'Le principe de continuité affirme qu’une même couche a le même âge sur toute son extension.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Même si son faciès change latéralement, du calcaire à la marne par exemple.', 5),
    ('6c2dc327-f003-51f3-aaf0-55a67699fe30'::uuid, '116c8b51-0cd5-5df0-ab0c-d8577614ec1a'::uuid, 'Comment reconnaître qu’une série sédimentaire a été renversée ?', 'mcq', '["Grâce aux figures sédimentaires, comme le granoclassement","Grâce à la radiochronologie","Grâce à la couleur des roches","On ne peut pas le savoir"]'::jsonb, 0, 'Ces figures indiquent le haut d’origine de la couche, indépendamment de sa position actuelle.', 6),
    ('6c2efbc0-ac2e-584f-96c4-2111e8e8578e'::uuid, '116c8b51-0cd5-5df0-ab0c-d8577614ec1a'::uuid, 'L’échelle stratigraphique a été construite AVANT que l’on sache dater en millions d’années.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La radiochronologie n’a fait que la calibrer, au XXᵉ siècle.', 7),
    ('becae06f-ffc2-556e-ace2-f3250f3c26f5'::uuid, '116c8b51-0cd5-5df0-ab0c-d8577614ec1a'::uuid, 'Une surface d’érosion qui tronque des couches plissées est…', 'mcq', '["Postérieure au plissement","Antérieure au plissement","Contemporaine du dépôt","Sans rapport chronologique"]'::jsonb, 0, 'Elle recoupe le plissement, donc elle lui succède.', 8),
    ('1edd250b-2b73-5df4-aea3-90288a793367'::uuid, '50d37a24-61cb-5b01-9c6f-95e1ea957ecc'::uuid, 'Que signifie la demi-vie d’un isotope radioactif ?', 'mcq', '["La durée au bout de laquelle la moitié des atomes pères s’est désintégrée","La durée de vie totale de l’isotope","La moitié de l’âge de la roche","Le temps de refroidissement du magma"]'::jsonb, 0, 'La décroissance est exponentielle : il reste 1/4 après deux demi-vies.', 1),
    ('fa7d079b-12cd-593f-88fc-16cbd1db1367'::uuid, '50d37a24-61cb-5b01-9c6f-95e1ea957ecc'::uuid, 'La vitesse de désintégration dépend de la température et de la pression.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est justement son indifférence aux conditions qui en fait une horloge fiable.', 2),
    ('10d03aa9-38cf-59ce-ae43-f6406eb9381e'::uuid, '50d37a24-61cb-5b01-9c6f-95e1ea957ecc'::uuid, 'Quel couple utilise-t-on pour dater de la matière organique récente ?', 'mcq', '["Carbone 14 / azote 14","Potassium 40 / argon 40","Rubidium 87 / strontium 87","Uranium / plomb"]'::jsonb, 0, 'Sa demi-vie de 5 730 ans le limite à environ 50 000 ans.', 3),
    ('80335b83-7f85-5ea2-8303-e67f4eac0623'::uuid, '50d37a24-61cb-5b01-9c6f-95e1ea957ecc'::uuid, 'Pourquoi ne date-t-on pas une roche d’un milliard d’années au carbone 14 ?', 'mcq', '["Sa demi-vie est bien trop courte : il ne reste plus d’atomes pères","Le carbone 14 n’existe pas dans les roches volcaniques","La mesure coûte trop cher","Le carbone 14 se désintègre trop lentement"]'::jsonb, 0, 'Il faut choisir un couple dont la demi-vie est de l’ordre de l’âge cherché.', 4),
    ('7d5c2f57-a56a-5ba9-8a0b-d136d2a51e01'::uuid, '50d37a24-61cb-5b01-9c6f-95e1ea957ecc'::uuid, 'Que date exactement une mesure faite sur une roche magmatique ?', 'mcq', '["Sa cristallisation, c’est-à-dire la fermeture du système","Son érosion","Son enfouissement","Sa dernière déformation"]'::jsonb, 0, 'L’horloge démarre quand le minéral cesse d’échanger avec l’extérieur.', 5),
    ('83e43db6-2f61-598e-9b73-7783584316d8'::uuid, '50d37a24-61cb-5b01-9c6f-95e1ea957ecc'::uuid, 'Une datation radiochronologique suppose que le système est resté fermé.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Si des atomes fils sont partis ou entrés, l’âge obtenu est faux.', 6),
    ('139304fa-d461-5087-9aa4-c073b491f01d'::uuid, '50d37a24-61cb-5b01-9c6f-95e1ea957ecc'::uuid, 'Quel âge donne-t-on aujourd’hui à la Terre ?', 'mcq', '["Environ 4,57 milliards d’années","Environ 570 millions d’années","Environ 45 millions d’années","Environ 13,8 milliards d’années"]'::jsonb, 0, 'Obtenu sur des météorites au couple uranium-plomb.', 7),
    ('e1501d32-cafc-5244-af83-46accaf9af32'::uuid, '50d37a24-61cb-5b01-9c6f-95e1ea957ecc'::uuid, 'À quoi sert de croiser chronologie relative et chronologie absolue ?', 'mcq', '["La datation d’une coulée volcanique encadre les couches situées au-dessus et en dessous","À vérifier deux fois le même résultat","À remplacer les fossiles stratigraphiques","À mesurer la vitesse de sédimentation seule"]'::jsonb, 0, 'C’est ainsi que l’échelle stratigraphique a été calibrée en millions d’années.', 8),
    ('98b085dd-28fc-5a50-a347-e066871bafb3'::uuid, 'c01e79c0-e616-583c-90fa-820662e294ae'::uuid, 'Quelles structures caractérisent la phase de rifting ?', 'mcq', '["Des failles normales et des blocs basculés","Des failles inverses et des chevauchements","Des nappes de charriage","Des éclogites"]'::jsonb, 0, 'Le rifting est une phase d’EXTENSION : la lithosphère s’amincit et se casse.', 1),
    ('82c74970-525d-5aae-92d9-eb3baeec1652'::uuid, 'c01e79c0-e616-583c-90fa-820662e294ae'::uuid, 'Qu’est-ce qu’une ophiolite ?', 'mcq', '["Un fragment de lithosphère océanique charrié sur un continent","Une roche du noyau terrestre","Un sédiment de marge passive","Une roche métamorphique de collision"]'::jsonb, 0, 'Sa séquence péridotites-gabbros-basaltes en coussins signe une origine océanique.', 2),
    ('6871ebd9-1227-5a84-b3e8-793261f77fa9'::uuid, 'c01e79c0-e616-583c-90fa-820662e294ae'::uuid, 'Les basaltes en coussins se forment lors d’un refroidissement sous l’eau.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ces pillow-lavas sont un marqueur direct d’un volcanisme sous-marin.', 3),
    ('a9745342-299b-5107-aef9-8a3f79936345'::uuid, 'c01e79c0-e616-583c-90fa-820662e294ae'::uuid, 'Pourquoi une lithosphère océanique finit-elle par plonger en subduction ?', 'mcq', '["En refroidissant elle s’épaissit et devient plus dense que l’asthénosphère","Parce qu’elle est poussée par la dorsale seule","Parce qu’elle s’allège avec l’âge","Parce que les sédiments l’alourdissent"]'::jsonb, 0, 'Le basculement de densité intervient au-delà d’environ 30 millions d’années.', 4),
    ('5833e142-51ab-5d7b-81c6-3bd53c35ca9f'::uuid, 'c01e79c0-e616-583c-90fa-820662e294ae'::uuid, 'Quel minéral signe un métamorphisme haute pression - basse température ?', 'mcq', '["Le glaucophane","Le quartz","La calcite","L’olivine"]'::jsonb, 0, 'On le trouve dans les métagabbros alpins, avant les éclogites à grenat et jadéite.', 5),
    ('5f10d9e8-5173-5829-a312-3dd7a0a68222'::uuid, 'c01e79c0-e616-583c-90fa-820662e294ae'::uuid, 'Comment la subduction déclenche-t-elle un magmatisme ?', 'mcq', '["La déshydratation des minéraux abaisse la température de fusion du manteau","Le frottement fait fondre la plaque plongeante","La pression seule liquéfie les roches","Le noyau remonte de la chaleur"]'::jsonb, 0, 'L’eau libérée provoque une fusion partielle hydratée du manteau sus-jacent.', 6),
    ('24b0d821-1a20-5c9f-a19e-98837f28fcbe'::uuid, 'c01e79c0-e616-583c-90fa-820662e294ae'::uuid, 'Une chaîne de collision présente un épaississement crustal et une racine.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La croûte peut y atteindre 70 km, contre 30 km en moyenne sous un continent.', 7),
    ('6dedaf92-3491-5310-8315-dbcb36977f8f'::uuid, 'c01e79c0-e616-583c-90fa-820662e294ae'::uuid, 'Pourquoi trouve-t-on aujourd’hui en surface des roches formées à 30 km de profondeur ?', 'mcq', '["L’isostasie fait remonter la chaîne à mesure que l’érosion la rabote","Elles ont été projetées par un volcan","Elles se sont formées sur place","Un océan les a déposées"]'::jsonb, 0, 'Érosion et rééquilibrage isostatique exhument peu à peu les racines de la chaîne.', 8),
    ('5d69274b-86d8-59db-9151-fbd65e10fa19'::uuid, '723388dc-85d8-56c3-b78b-1985497feeef'::uuid, 'Quelle contrainte majeure explique l’organisation d’une plante à fleurs ?', 'mcq', '["La vie fixée : elle ne peut ni fuir ni chercher ses ressources","Sa petite taille","Son absence de cellules","Sa reproduction asexuée obligatoire"]'::jsonb, 0, 'Elle doit tout prélever sur place, dans le sol et dans l’atmosphère.', 1),
    ('a165e44e-f770-56ab-94d9-e40a47b93b74'::uuid, '723388dc-85d8-56c3-b78b-1985497feeef'::uuid, 'Que gagne une plante à s’associer à un champignon dans une mycorhize ?', 'mcq', '["Une surface d’absorption accrue et un meilleur accès au phosphore","Du dioxygène supplémentaire","Une protection contre le froid","La capacité de se déplacer"]'::jsonb, 0, 'Le champignon reçoit en échange des sucres issus de la photosynthèse.', 2),
    ('8750f048-46ef-5967-be1e-2c375596471c'::uuid, '723388dc-85d8-56c3-b78b-1985497feeef'::uuid, 'Les stomates sont surtout situés sur la face inférieure des feuilles.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Cette position limite l’évaporation due à l’ensoleillement direct.', 3),
    ('c822ae92-31ea-5047-97d7-75deaf75fe94'::uuid, '723388dc-85d8-56c3-b78b-1985497feeef'::uuid, 'Quel compromis les stomates imposent-ils ?', 'mcq', '["Laisser entrer le CO₂ oblige à laisser sortir de l’eau","Absorber la lumière empêche d’absorber l’eau","Fleurir empêche de croître","Produire du sucre empêche de respirer"]'::jsonb, 0, 'Fermés, ils économisent l’eau mais arrêtent la photosynthèse.', 4),
    ('09bb3a4e-ee0f-55d8-9db0-bc89d8ccf60c'::uuid, '723388dc-85d8-56c3-b78b-1985497feeef'::uuid, 'Quel est le moteur de la montée de la sève brute dans le xylème ?', 'mcq', '["La transpiration foliaire, qui tire la colonne d’eau","Une pompe située dans la racine","La pesanteur","La pression du phloème"]'::jsonb, 0, 'La cohésion des molécules d’eau maintient la colonne sous tension.', 5),
    ('14db0e13-dbb7-5750-9d17-0c5fe9709bb4'::uuid, '723388dc-85d8-56c3-b78b-1985497feeef'::uuid, 'Le phloème transporte la sève élaborée dans les deux sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Des feuilles productrices vers tout organe consommateur ou de réserve.', 6),
    ('1a0cd5a6-fb1f-5eca-9d4a-844f3eb89fbe'::uuid, '723388dc-85d8-56c3-b78b-1985497feeef'::uuid, 'Que sont la nicotine, la caféine et les tanins ?', 'mcq', '["Des métabolites secondaires défensifs","Des pigments photosynthétiques","Des hormones de croissance","Des sucres de réserve"]'::jsonb, 0, 'Ils rendent la plante toxique ou répulsive pour les herbivores.', 7),
    ('28f436be-dddb-5fac-8a0b-69d0228c138b'::uuid, '723388dc-85d8-56c3-b78b-1985497feeef'::uuid, 'Comment une plante à l’ombre modifie-t-elle son développement ?', 'mcq', '["Elle s’allonge pour atteindre la lumière","Elle cesse de croître définitivement","Elle perd ses racines","Elle ferme ses stomates en permanence"]'::jsonb, 0, 'La croissance des méristèmes reste sensible aux conditions du milieu toute la vie.', 8),
    ('a461fd5f-44a5-549a-a61e-e87ad234c4ff'::uuid, '51d8c2f5-631c-57dd-92c2-9ae14c8b2789'::uuid, 'D’où provient le dioxygène rejeté par la photosynthèse ?', 'mcq', '["De l’eau, oxydée lors de la photolyse","Du dioxyde de carbone","Du glucose","De l’air absorbé par les stomates"]'::jsonb, 0, 'C’est la photolyse de l’eau dans les thylakoïdes qui libère l’O₂.', 1),
    ('f5f68755-6401-5b76-9206-16aafea6d93f'::uuid, '51d8c2f5-631c-57dd-92c2-9ae14c8b2789'::uuid, 'Où se déroule la phase photochimique de la photosynthèse ?', 'mcq', '["Dans les thylakoïdes du chloroplaste","Dans le stroma","Dans la mitochondrie","Dans le noyau"]'::jsonb, 0, 'C’est là que sont logés les pigments qui captent la lumière.', 2),
    ('235a680e-eb24-500a-8446-bbff07397e0e'::uuid, '51d8c2f5-631c-57dd-92c2-9ae14c8b2789'::uuid, 'Le cycle de Calvin utilise l’ATP et les RH₂ pour réduire le CO₂.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il se déroule dans le stroma, et dépend donc indirectement de la lumière.', 3),
    ('ea792ae7-546a-573f-b37e-0b87b3474ee9'::uuid, '51d8c2f5-631c-57dd-92c2-9ae14c8b2789'::uuid, 'Quelle enzyme fixe le CO₂ dans le cycle de Calvin ?', 'mcq', '["La RuBisCO","L’ATP synthase","La chlorophylle","L’amylase"]'::jsonb, 0, 'Elle fixe le CO₂ sur un sucre à 5 carbones ; c’est la protéine la plus abondante de la biosphère.', 4),
    ('ce564bdc-075d-5b85-8d37-4803bb641fd3'::uuid, '51d8c2f5-631c-57dd-92c2-9ae14c8b2789'::uuid, 'Que montre la superposition du spectre d’action et du spectre d’absorption ?', 'mcq', '["Que ce sont bien les pigments qui captent l’énergie utilisée","Que la chlorophylle est verte","Que la lumière verte est la plus efficace","Que le CO₂ absorbe la lumière"]'::jsonb, 0, 'L’efficacité photosynthétique est maximale là où les pigments absorbent : bleu et rouge.', 5),
    ('76e10ffd-a5ea-5876-bda4-490237dccde5'::uuid, '51d8c2f5-631c-57dd-92c2-9ae14c8b2789'::uuid, 'Les feuilles sont vertes parce que la chlorophylle absorbe le vert.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle le RÉFLÉCHIT : elle absorbe surtout le bleu et le rouge.', 6),
    ('ede0cbae-337a-53d3-9e8a-449fa56fce16'::uuid, '51d8c2f5-631c-57dd-92c2-9ae14c8b2789'::uuid, 'Sous quelle forme la plante stocke-t-elle le glucose en réserve ?', 'mcq', '["En amidon","En cellulose","En saccharose dans le xylème","En ATP"]'::jsonb, 0, 'La cellulose, elle, sert de charpente dans la paroi des cellules.', 7),
    ('5ca26912-2119-5e61-8462-4726837c2e2d'::uuid, '51d8c2f5-631c-57dd-92c2-9ae14c8b2789'::uuid, 'À quoi servent les métabolites secondaires ?', 'mcq', '["À la défense, à l’attraction des pollinisateurs et à la compétition","À la croissance des tiges","À la respiration cellulaire","À la circulation de la sève"]'::jsonb, 0, 'Alcaloïdes, tanins, terpènes : ce sont eux qui intéressent pharmacie et parfumerie.', 8),
    ('7126e57e-8478-57dd-a44b-d3d5eaa0460f'::uuid, '8317cc28-a465-5d94-a4f9-50afef9a014f'::uuid, 'Quel verticille de la fleur produit le pollen ?', 'mcq', '["Les étamines","Les pétales","Les sépales","Le pistil"]'::jsonb, 0, 'Le pistil, lui, contient les ovules dans son ovaire.', 1),
    ('ee6855a4-f385-5de1-9b8f-6c6229787a1e'::uuid, '8317cc28-a465-5d94-a4f9-50afef9a014f'::uuid, 'Quelles caractéristiques trahissent une fleur pollinisée par le vent ?', 'mcq', '["Fleurs discrètes, pollen léger produit en grande quantité","Pétales colorés et nectar abondant","Pollen lourd et collant","Fleurs très odorantes"]'::jsonb, 0, 'L’anémogamie gaspille beaucoup de pollen — d’où les allergies au printemps.', 2),
    ('135ea5e5-d8e8-5816-8d6f-9bf1df441b16'::uuid, '8317cc28-a465-5d94-a4f9-50afef9a014f'::uuid, 'La pollinisation par les animaux est plus économe en pollen que par le vent.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le transport est ciblé : il faut produire beaucoup moins de grains.', 3),
    ('585af9d5-9c8b-52b5-860c-c5d32ede05a4'::uuid, '8317cc28-a465-5d94-a4f9-50afef9a014f'::uuid, 'Qu’illustre l’orchidée à long éperon prédite par Darwin ?', 'mcq', '["La coévolution entre une plante et son pollinisateur","La multiplication végétative","L’anémogamie","L’autofécondation"]'::jsonb, 0, 'Le papillon à trompe de 30 cm annoncé en 1862 fut découvert quarante ans plus tard.', 4),
    ('d45518f1-850c-5045-8d64-70dbddde4cb5'::uuid, '8317cc28-a465-5d94-a4f9-50afef9a014f'::uuid, 'Que devient l’ovule après la fécondation ?', 'mcq', '["La graine","Le fruit","Le stigmate","L’étamine"]'::jsonb, 0, 'C’est l’ovaire, lui, qui devient le fruit.', 5),
    ('c62bcc11-3ea9-59d2-9e58-bb57cd4bde4f'::uuid, '8317cc28-a465-5d94-a4f9-50afef9a014f'::uuid, 'La dioécie — des sexes sur des pieds différents — favorise l’autofécondation.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle l’INTERDIT : c’est un dispositif qui impose la fécondation croisée.', 6),
    ('45f0a441-18fc-51bf-a03e-2f8309a7b2e1'::uuid, '8317cc28-a465-5d94-a4f9-50afef9a014f'::uuid, 'Quel mode de dissémination correspond à un fruit charnu et sucré ?', 'mcq', '["La zoochorie : il est mangé et la graine rejetée plus loin","L’anémochorie","La dispersion par l’eau","L’autodissémination explosive"]'::jsonb, 0, 'La samare de l’érable, elle, mise sur le vent.', 7),
    ('62238105-8d11-5210-9d71-9de21b2398aa'::uuid, '8317cc28-a465-5d94-a4f9-50afef9a014f'::uuid, 'Quel avantage la multiplication végétative offre-t-elle sur la reproduction sexuée ?', 'mcq', '["Occuper vite et sûrement un milieu déjà favorable","Créer de la diversité génétique","Disperser les descendants au loin","Résister aux parasites"]'::jsonb, 0, 'Elle produit un clone : rapidité contre absence de diversité nouvelle.', 8),
    ('2e496608-c6d0-55e4-afe1-9b259c6cfb6b'::uuid, '88101785-4a97-5a48-a59e-2f75f583f53b'::uuid, 'Quand la domestication des plantes a-t-elle commencé ?', 'mcq', '["Il y a environ 10 000 ans, au Néolithique","Il y a environ 500 ans","Au XIXᵉ siècle","Il y a environ 100 000 ans"]'::jsonb, 0, 'Elle est apparue indépendamment dans plusieurs foyers : Proche-Orient, Chine, Mésoamérique.', 1),
    ('9e3c03cb-1be9-5124-9577-3c50e5df49b4'::uuid, '88101785-4a97-5a48-a59e-2f75f583f53b'::uuid, 'Quel caractère a été sélectionné involontairement en ressemant les récoltes ?', 'mcq', '["Des épis qui ne se désarticulent pas","Des graines qui se dispersent seules","Des racines plus profondes","Une floraison plus tardive"]'::jsonb, 0, 'Les plantes qui perdent leurs graines au sol ne sont tout simplement pas récoltées.', 2),
    ('8b5c8ecf-9ffd-5524-b811-c6c401172840'::uuid, '88101785-4a97-5a48-a59e-2f75f583f53b'::uuid, 'Les plantes cultivées se disséminent en général mieux que leurs ancêtres sauvages.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est l’inverse : elles en sont devenues incapables et dépendent de l’humain.', 3),
    ('86325f6a-3e99-5d04-ac3f-72680dbce5cb'::uuid, '88101785-4a97-5a48-a59e-2f75f583f53b'::uuid, 'Quelle est l’ancêtre sauvage du maïs ?', 'mcq', '["La téosinte","Le blé sauvage","Le riz sauvage","Le sorgho"]'::jsonb, 0, 'Son épi minuscule et cassant portait une dizaine de grains durs.', 4),
    ('6e2cb494-178d-5d5f-a8cc-c17fe911db69'::uuid, '88101785-4a97-5a48-a59e-2f75f583f53b'::uuid, 'Qu’est-ce que la vigueur hybride ?', 'mcq', '["La supériorité d’un hybride F1 sur ses deux lignées parentales","La résistance naturelle des plantes sauvages","La vitesse de germination des graines","Le rendement des variétés anciennes"]'::jsonb, 0, 'Elle est perdue dès la F2, ce qui oblige à racheter des semences chaque année.', 5),
    ('34d528cd-baa9-54a3-a49e-78c8d4a99429'::uuid, '88101785-4a97-5a48-a59e-2f75f583f53b'::uuid, 'La transgenèse introduit un gène précis, éventuellement d’une autre espèce.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Contrairement à la mutagenèse, qui provoque des mutations au hasard puis trie.', 6),
    ('e6e5cb05-bb39-54fc-8321-328b8a2adb9f'::uuid, '88101785-4a97-5a48-a59e-2f75f583f53b'::uuid, 'Pourquoi l’uniformité génétique des cultures est-elle un risque ?', 'mcq', '["Un seul parasite adapté peut ravager toute la culture","Elle réduit les rendements immédiats","Elle empêche la photosynthèse","Elle interdit la reproduction sexuée"]'::jsonb, 0, 'Le mildiou de la pomme de terre en Irlande, en 1845, en est l’exemple historique.', 7),
    ('345d2105-c7d4-5940-86e1-664300e00eeb'::uuid, '88101785-4a97-5a48-a59e-2f75f583f53b'::uuid, 'À quoi servent les banques de semences comme celle du Svalbard ?', 'mcq', '["À conserver des allèles pour les sélections futures","À produire des OGM","À stocker des engrais","À remplacer les variétés paysannes"]'::jsonb, 0, 'Elles conservent près d’un million d’échantillons, dont des apparentés sauvages.', 8),
    ('41f7a993-360a-5edd-9124-77a87f12a505'::uuid, '89c807f9-b1dc-5c05-a290-abe57c38d338'::uuid, 'Quelle serait la température moyenne de surface sans effet de serre ?', 'mcq', '["Environ −18 °C","Environ 0 °C","Environ +15 °C","Environ +30 °C"]'::jsonb, 0, 'L’effet de serre naturel apporte donc plus de 30 °C : c’est son renforcement qui pose problème.', 1),
    ('c4edc1d8-266a-5dc5-a469-f3461d5ca4c6'::uuid, '89c807f9-b1dc-5c05-a290-abe57c38d338'::uuid, 'Quel est l’ordre de grandeur de l’albédo terrestre moyen ?', 'mcq', '["Environ 30 %","Environ 5 %","Environ 70 %","Environ 95 %"]'::jsonb, 0, 'C’est la part du rayonnement solaire directement renvoyée vers l’espace.', 2),
    ('3365348d-d470-5ec0-add0-80624b8b72eb'::uuid, '89c807f9-b1dc-5c05-a290-abe57c38d338'::uuid, 'Quel cycle de Milankovitch dure environ 100 000 ans ?', 'mcq', '["L’excentricité de l’orbite","L’obliquité de l’axe","La précession des équinoxes","Le cycle solaire"]'::jsonb, 0, 'L’obliquité tourne autour de 41 000 ans et la précession de 21 000 ans.', 3),
    ('37efe2c8-daaf-5e09-ad1c-2d84730544f4'::uuid, '89c807f9-b1dc-5c05-a290-abe57c38d338'::uuid, 'Les paramètres orbitaux modifient la quantité TOTALE d’énergie reçue du Soleil.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils en modifient surtout la RÉPARTITION dans le temps et selon la latitude.', 4),
    ('a430c7a8-6112-5a46-a950-f3c5848ae2ef'::uuid, '89c807f9-b1dc-5c05-a290-abe57c38d338'::uuid, 'Comment fonctionne la rétroaction positive de l’albédo ?', 'mcq', '["Plus de glace augmente l’albédo, ce qui refroidit encore davantage","Plus de glace réchauffe l’atmosphère","L’albédo stabilise le climat","L’albédo n’agit que sur les océans"]'::jsonb, 0, 'Le mécanisme s’emballe aussi dans l’autre sens lors d’un réchauffement.', 5),
    ('8deff368-2985-5967-84c2-8420e31cddec'::uuid, '89c807f9-b1dc-5c05-a290-abe57c38d338'::uuid, 'Pourquoi les cycles de Milankovitch suffisent-ils à déclencher une glaciation ?', 'mcq', '["Parce que des rétroactions amplifient leur effet direct, faible","Parce qu’ils modifient fortement la constante solaire","Parce qu’ils déplacent les continents","Parce qu’ils augmentent le volcanisme"]'::jsonb, 0, 'Ils déclenchent ; albédo, CO₂ océanique et vapeur d’eau amplifient.', 6),
    ('8eb41d84-5926-5676-9eab-ed94a632238e'::uuid, '89c807f9-b1dc-5c05-a290-abe57c38d338'::uuid, 'L’altération des silicates des chaînes de montagnes consomme du CO₂ atmosphérique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La surrection de l’Himalaya a sans doute contribué au refroidissement du Cénozoïque.', 7),
    ('512e8ca3-5f45-5dae-b888-e0f872d14dea'::uuid, '89c807f9-b1dc-5c05-a290-abe57c38d338'::uuid, 'Que représentent les combustibles fossiles dans le cycle du carbone ?', 'mcq', '["Du carbone soustrait à l’atmosphère par enfouissement, que nous relâchons","Du carbone d’origine volcanique récente","Du carbone venu de l’espace","Du carbone dissous dans l’océan profond"]'::jsonb, 0, 'Des millions d’années d’enfouissement rebrûlées en quelques siècles.', 8),
    ('41aea9be-3c27-5685-94a9-5ba09e6630a7'::uuid, '682a18ff-ebce-5286-ab9e-c91e8695dd26'::uuid, 'Que contiennent les bulles d’air piégées dans une carotte de glace ?', 'mcq', '["Un échantillon direct de l’atmosphère ancienne","De l’eau de fonte","Des pollens fossiles","Du carbone 14"]'::jsonb, 0, 'On y mesure directement les teneurs passées en CO₂ et en méthane.', 1),
    ('5eb88dd5-d43b-53cc-8e47-9cbc0a117525'::uuid, '682a18ff-ebce-5286-ab9e-c91e8695dd26'::uuid, 'Jusqu’à quelle ancienneté remontent les plus longues carottes de glace antarctiques ?', 'mcq', '["Environ 800 000 ans","Environ 8 000 ans","Environ 80 000 ans","Environ 8 millions d’années"]'::jsonb, 0, 'La carotte EPICA Dome C fait référence pour cette échelle.', 2),
    ('f32c94e4-8dfd-5154-b246-046bb5d1bf11'::uuid, '682a18ff-ebce-5286-ab9e-c91e8695dd26'::uuid, 'Le δ18O de la glace renseigne sur la température au moment de la précipitation.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Une glace pauvre en isotopes lourds s’est déposée par temps froid.', 3),
    ('2025605e-846a-5fb2-a31f-e565738605f5'::uuid, '682a18ff-ebce-5286-ab9e-c91e8695dd26'::uuid, 'De quoi dépend le δ18O des tests de foraminifères ?', 'mcq', '["De la température de l’eau et du volume des glaces","De la profondeur seule","De la salinité seule","De l’âge de l’organisme"]'::jsonb, 0, 'Les glaces piègent l’isotope léger et enrichissent l’océan en isotope lourd.', 4),
    ('97266cb5-4cde-561f-87e0-ca3d771d9dda'::uuid, '682a18ff-ebce-5286-ab9e-c91e8695dd26'::uuid, 'Quelle archive offre la meilleure résolution temporelle ?', 'mcq', '["Les cernes des arbres, avec une résolution annuelle","Les sédiments marins","Les pollens","Les moraines"]'::jsonb, 0, 'Sa portée est en revanche limitée à quelques milliers d’années.', 5),
    ('f01f7615-f830-59cf-b4dc-eb5d591802fe'::uuid, '682a18ff-ebce-5286-ab9e-c91e8695dd26'::uuid, 'Les pollens fossiles renseignent sur la végétation, donc sur le climat local.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Chaque espèce a un pollen reconnaissable et des exigences climatiques connues.', 6),
    ('e0e3674a-fec4-5658-8fdd-7ddc4741a3ae'::uuid, '682a18ff-ebce-5286-ab9e-c91e8695dd26'::uuid, 'Quelle archive donne à la fois la température ET la composition de l’atmosphère ?', 'mcq', '["Les carottes de glace","Les cernes des arbres","Les moraines glaciaires","Les registres de vendanges"]'::jsonb, 0, 'C’est ce qui permet d’établir que CO₂ et température varient de concert.', 7),
    ('fee5e1c2-bef1-5c7b-85d0-9ca25dc59ae3'::uuid, '682a18ff-ebce-5286-ab9e-c91e8695dd26'::uuid, 'Comment teste-t-on la fiabilité d’un modèle climatique ?', 'mcq', '["En vérifiant qu’il reproduit les climats passés reconstitués","En comparant deux modèles entre eux","En attendant cinquante ans","En mesurant la température actuelle"]'::jsonb, 0, 'C’est le principal argument de crédit accordé aux projections futures.', 8),
    ('5d97c9b1-fc27-51a2-8346-5e6a45a2058d'::uuid, '7c848f7f-f038-52b7-98cd-4750f6da9fc4'::uuid, 'De combien la teneur atmosphérique en CO₂ est-elle passée depuis l’ère préindustrielle ?', 'mcq', '["D’environ 280 ppm à plus de 420 ppm","D’environ 100 ppm à 200 ppm","D’environ 1 000 ppm à 420 ppm","Elle n’a pas changé"]'::jsonb, 0, 'Une valeur jamais atteinte depuis au moins 800 000 ans, d’après les carottes de glace.', 1),
    ('277af695-d65d-5db1-ab96-732b8ad3ff64'::uuid, '7c848f7f-f038-52b7-98cd-4750f6da9fc4'::uuid, 'Quel réchauffement moyen a déjà été mesuré depuis 1850-1900 ?', 'mcq', '["Environ 1,1 à 1,2 °C","Environ 0,1 °C","Environ 4 °C","Environ 10 °C"]'::jsonb, 0, 'Avec de fortes disparités régionales, l’Arctique se réchauffant bien plus vite.', 2),
    ('1c884a54-292d-566f-b951-16ffe7d134a6'::uuid, '7c848f7f-f038-52b7-98cd-4750f6da9fc4'::uuid, 'La fonte de la banquise arctique fait monter le niveau des mers.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle flotte déjà : seules les glaces CONTINENTALES et la dilatation thermique font monter le niveau.', 3),
    ('687b3720-7a5a-5c48-acac-a6b2d7182f31'::uuid, '7c848f7f-f038-52b7-98cd-4750f6da9fc4'::uuid, 'Quelle est la cause de l’acidification de l’océan ?', 'mcq', '["L’absorption d’une partie du CO₂ émis","La fonte des glaciers","La hausse de température seule","Les pluies acides"]'::jsonb, 0, 'L’océan a absorbé environ un quart des émissions, ce qui abaisse son pH.', 4),
    ('013698f7-3d10-5186-b3b8-02b6d7da0b76'::uuid, '7c848f7f-f038-52b7-98cd-4750f6da9fc4'::uuid, 'Quel est le rôle du GIEC ?', 'mcq', '["Évaluer l’ensemble de la littérature scientifique publiée","Réaliser ses propres expériences","Fixer les politiques climatiques des États","Mesurer la température mondiale"]'::jsonb, 0, 'Il produit une synthèse, pas de la recherche originale.', 5),
    ('a8627065-4c8c-5d53-a89c-eff8f5dece89'::uuid, '7c848f7f-f038-52b7-98cd-4750f6da9fc4'::uuid, 'Quelle est la différence entre atténuation et adaptation ?', 'mcq', '["L’atténuation réduit les émissions, l’adaptation limite les dommages","L’atténuation est locale, l’adaptation mondiale","L’adaptation réduit les émissions","Ce sont deux mots pour la même chose"]'::jsonb, 0, 'L’une agit sur la cause, l’autre sur les conséquences ; les deux sont nécessaires.', 6),
    ('296115dc-5b73-5bf9-aa1a-11b1c9571a85'::uuid, '7c848f7f-f038-52b7-98cd-4750f6da9fc4'::uuid, 'Renforcer les puits de carbone suffit à compenser les émissions actuelles.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils absorbent déjà environ la moitié des émissions, mais un puits saturé ne stocke plus.', 7),
    ('f73d4d52-f012-570c-868d-bb3bbf8d1402'::uuid, '7c848f7f-f038-52b7-98cd-4750f6da9fc4'::uuid, 'Qu’appelle-t-on désynchronisation dans un écosystème qui se réchauffe ?', 'mcq', '["Une fleur qui s’ouvre avant l’arrivée de son pollinisateur","Le décalage des saisons touristiques","La migration des continents","La variation du δ18O"]'::jsonb, 0, 'Les espèces ne décalent pas leur calendrier au même rythme.', 8),
    ('7aa3234c-2433-5b0b-acd4-c52fed8ae06a'::uuid, '8c63cc4b-28d3-5a8a-9fd3-31fa742d4be9'::uuid, 'Quel récepteur déclenche le réflexe myotatique ?', 'mcq', '["Le fuseau neuromusculaire, sensible à l’étirement","Le corpuscule tactile de la peau","Le motoneurone","La synapse neuromusculaire"]'::jsonb, 0, 'Il est logé dans le muscle lui-même et détecte sa mise en tension.', 1),
    ('1110a88d-5546-5853-97fd-16dfbf2ea781'::uuid, '8c63cc4b-28d3-5a8a-9fd3-31fa742d4be9'::uuid, 'Quel centre nerveux intègre le réflexe myotatique ?', 'mcq', '["La moelle épinière","Le cortex moteur","Le cervelet","L’hypothalamus"]'::jsonb, 0, 'Le cerveau n’intervient pas : c’est ce qui rend la réponse aussi rapide.', 2),
    ('20c9b954-c62e-569d-8b89-70cb3f9e7ac5'::uuid, '8c63cc4b-28d3-5a8a-9fd3-31fa742d4be9'::uuid, 'Le réflexe myotatique est monosynaptique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Une seule synapse sépare le neurone sensitif du motoneurone.', 3),
    ('624ed2b6-c2f7-567a-9f9b-29ca6ac32bf8'::uuid, '8c63cc4b-28d3-5a8a-9fd3-31fa742d4be9'::uuid, 'Comment l’intensité d’un stimulus est-elle codée dans une fibre nerveuse ?', 'mcq', '["Par la fréquence des potentiels d’action","Par leur amplitude","Par leur durée individuelle","Par le nombre de synapses traversées"]'::jsonb, 0, 'Les potentiels d’action sont tous identiques : c’est la loi du tout ou rien.', 4),
    ('26047a35-ed4a-5c39-9993-5f4870eb4c28'::uuid, '8c63cc4b-28d3-5a8a-9fd3-31fa742d4be9'::uuid, 'Quel neurotransmetteur agit à la jonction neuromusculaire ?', 'mcq', '["L’acétylcholine","La dopamine","L’adrénaline","Le cortisol"]'::jsonb, 0, 'Elle est libérée par exocytose dans la fente synaptique.', 5),
    ('680fa72a-51ea-5a3f-97c7-271ac8bed53e'::uuid, '8c63cc4b-28d3-5a8a-9fd3-31fa742d4be9'::uuid, 'Au niveau d’une synapse, le message nerveux devient chimique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il est codé en concentration de neurotransmetteur libéré.', 6),
    ('d52edda5-79a3-5cc1-9c9f-e46a7e8567c8'::uuid, '8c63cc4b-28d3-5a8a-9fd3-31fa742d4be9'::uuid, 'Que fait un motoneurone qui reçoit des milliers de synapses ?', 'mcq', '["Il somme messages excitateurs et inhibiteurs et répond au-delà d’un seuil","Il transmet le premier message reçu","Il ignore les messages inhibiteurs","Il déclenche systématiquement un potentiel d’action"]'::jsonb, 0, 'C’est cette intégration qui rend le réflexe modulable par le cerveau.', 7),
    ('7e6c2367-45c8-5026-8d49-455232fed19b'::uuid, '8c63cc4b-28d3-5a8a-9fd3-31fa742d4be9'::uuid, 'À quoi sert un électromyogramme en clinique ?', 'mcq', '["À mesurer la vitesse de conduction et localiser une lésion nerveuse","À enregistrer l’activité du cortex","À mesurer la glycémie","À visualiser les muscles en trois dimensions"]'::jsonb, 0, 'Le réflexe devient alors un outil de diagnostic neurologique.', 8),
    ('1bb6bb50-f190-5558-bb0f-d2bb9d1d5c86'::uuid, 'e26817a0-6c93-53fe-ac86-c8a9d34a9aa3'::uuid, 'Où se situe le cortex moteur primaire ?', 'mcq', '["Sur la circonvolution frontale ascendante, devant le sillon central","Dans le lobe occipital","Dans le cervelet","Dans la moelle épinière"]'::jsonb, 0, 'Sa cartographie y est somatotopique : chaque zone commande une partie du corps.', 1),
    ('fa7d662b-1d40-5695-8b84-6b503bcad042'::uuid, 'e26817a0-6c93-53fe-ac86-c8a9d34a9aa3'::uuid, 'Que représente l’homonculus moteur ?', 'mcq', '["Une carte déformée où chaque organe occupe une place liée à la finesse de son contrôle","Un modèle anatomique du cerveau","La forme réelle du cortex","Le trajet du faisceau pyramidal"]'::jsonb, 0, 'La main, la langue et les lèvres y occupent une surface démesurée.', 2),
    ('ba1e8d4d-93c3-54ff-a1ef-72e4b1729086'::uuid, 'e26817a0-6c93-53fe-ac86-c8a9d34a9aa3'::uuid, 'Le faisceau corticospinal croise la ligne médiane au niveau du bulbe rachidien.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'D’où le contrôle croisé : l’hémisphère gauche commande le côté droit du corps.', 3),
    ('9070a162-4a48-5c46-aac0-24c673ec19e7'::uuid, 'e26817a0-6c93-53fe-ac86-c8a9d34a9aa3'::uuid, 'Une lésion du cortex moteur gauche entraîne…', 'mcq', '["Une hémiplégie du côté droit","Une hémiplégie du côté gauche","Une paralysie totale","Une perte de la sensibilité seule"]'::jsonb, 0, 'La commande motrice est croisée : la paralysie est controlatérale.', 4),
    ('547231c3-80fb-5982-b3ad-bf75b7ee7c7c'::uuid, 'e26817a0-6c93-53fe-ac86-c8a9d34a9aa3'::uuid, 'Quelle structure est en cause dans la maladie de Parkinson ?', 'mcq', '["Les noyaux gris centraux","Le cortex visuel","La moelle épinière","Le fuseau neuromusculaire"]'::jsonb, 0, 'Ils interviennent dans l’initiation et l’automatisation des mouvements.', 5),
    ('321c98bb-c399-5fae-bf92-171e89b1b165'::uuid, 'e26817a0-6c93-53fe-ac86-c8a9d34a9aa3'::uuid, 'Chez un violoniste, la zone corticale des doigts de la main gauche est agrandie.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est la plasticité d’apprentissage : l’entraînement remodèle les cartes corticales.', 6),
    ('9801a071-a8ad-5cdd-bbe5-3f52fd5c4a90'::uuid, 'e26817a0-6c93-53fe-ac86-c8a9d34a9aa3'::uuid, 'Sur quoi repose la rééducation après un AVC ?', 'mcq', '["Sur la plasticité cérébrale : des régions voisines reprennent la fonction","Sur la repousse des axones sectionnés","Sur la multiplication des neurones lésés","Sur le seul repos"]'::jsonb, 0, 'La récupération se travaille, et d’autant mieux qu’elle commence tôt.', 7),
    ('e70297ff-a658-5b32-b24a-bda9713802d6'::uuid, 'e26817a0-6c93-53fe-ac86-c8a9d34a9aa3'::uuid, 'Que détecte l’IRM fonctionnelle ?', 'mcq', '["L’afflux de sang oxygéné qui accompagne l’activité neuronale","Les potentiels d’action un par un","La structure anatomique seule","La concentration en neurotransmetteurs"]'::jsonb, 0, 'Elle permet de cartographier les aires actives chez le sujet vivant.', 8),
    ('cbd03fd2-0755-5ffc-b6cf-94b0de525ee1'::uuid, '9d7efea3-b8a7-5450-8465-7824fe97a130'::uuid, 'Pourquoi une lésion cérébrale est-elle souvent définitive ?', 'mcq', '["Les neurones se renouvellent très peu","Le crâne empêche toute réparation","Le sang n’y circule pas","Les neurones ne communiquent plus entre eux"]'::jsonb, 0, 'Seule la plasticité, via des régions voisines, permet une récupération partielle.', 1),
    ('ca6af2cb-1860-5f2e-85dc-089da89a8dd6'::uuid, '9d7efea3-b8a7-5450-8465-7824fe97a130'::uuid, 'Que se passe-t-il lors d’un accident vasculaire cérébral ?', 'mcq', '["Une région du cerveau est brutalement privée d’oxygène","Les neurones se multiplient trop vite","La myéline se reforme en excès","La dopamine est libérée massivement"]'::jsonb, 0, 'Par obstruction ou rupture d’un vaisseau : c’est une urgence absolue.', 2),
    ('960683d9-b1ae-5bac-91a3-4faa373a415a'::uuid, '9d7efea3-b8a7-5450-8465-7824fe97a130'::uuid, 'Les commotions cérébrales répétées sont associées à des atteintes cognitives durables.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'D’où les protocoles de sortie du terrain dans les sports de contact.', 3),
    ('9833c3ed-5abf-515e-b860-c41b6683e269'::uuid, '9d7efea3-b8a7-5450-8465-7824fe97a130'::uuid, 'Quel neurotransmetteur est au cœur du système de récompense ?', 'mcq', '["La dopamine","L’acétylcholine","L’adrénaline","L’insuline"]'::jsonb, 0, 'Il valorise normalement ce qui est utile à la survie ; les drogues le court-circuitent.', 4),
    ('cd2d3053-8712-519d-b3c6-a20a8522938a'::uuid, '9d7efea3-b8a7-5450-8465-7824fe97a130'::uuid, 'Comment agissent les substances psychoactives ?', 'mcq', '["Au niveau des synapses, en perturbant les neurotransmetteurs","En détruisant directement le crâne","En modifiant l’ADN des neurones","En bloquant la circulation sanguine"]'::jsonb, 0, 'Elles miment un neurotransmetteur, bloquent sa recapture ou empêchent sa fixation.', 5),
    ('17387c79-4725-523d-9d85-68607f5681d0'::uuid, '9d7efea3-b8a7-5450-8465-7824fe97a130'::uuid, 'Qu’est-ce que la tolérance à une substance ?', 'mcq', '["Le cerveau réduit ses récepteurs, il faut augmenter les doses","Le corps élimine la substance plus vite","La substance devient inefficace définitivement","Le manque disparaît"]'::jsonb, 0, 'Elle prépare le terrain à la dépendance.', 6),
    ('3da00282-2e3c-5894-a6f6-6e794196d1c7'::uuid, '9d7efea3-b8a7-5450-8465-7824fe97a130'::uuid, 'Le cortex préfrontal achève sa maturation vers l’âge de 25 ans.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est ce qui rend le cerveau adolescent particulièrement vulnérable aux substances.', 7),
    ('e9ca83c6-5e51-5b40-ad37-4facd504c185'::uuid, '9d7efea3-b8a7-5450-8465-7824fe97a130'::uuid, 'Quel rôle le sommeil joue-t-il pour le cerveau ?', 'mcq', '["Il consolide les apprentissages et élimine les déchets métaboliques","Il augmente le nombre de neurones","Il ralentit la plasticité cérébrale","Il n’a aucun effet cognitif"]'::jsonb, 0, 'Sa privation chronique dégrade attention, mémoire et humeur.', 8),
    ('6d9dd949-89f5-5c41-888d-f8c7870fe882'::uuid, 'b9791678-053f-5d74-84c2-44141cf740bd'::uuid, 'Qu’est-ce qu’une fibre musculaire ?', 'mcq', '["Une cellule géante, allongée et plurinucléée","Un faisceau de plusieurs cellules","Un filament de myosine","Un tendon"]'::jsonb, 0, 'Elle provient de la fusion de plusieurs cellules, d’où ses nombreux noyaux.', 1),
    ('998c90f7-65b7-52e9-b523-610f19da92a2'::uuid, 'b9791678-053f-5d74-84c2-44141cf740bd'::uuid, 'Quelles protéines constituent les filaments du sarcomère ?', 'mcq', '["L’actine et la myosine","Le collagène et l’élastine","L’insuline et le glucagon","L’ATP et la créatine"]'::jsonb, 0, 'Les filaments fins d’actine sont ancrés sur les stries Z, les épais de myosine sont au centre.', 2),
    ('aca59ce0-f104-53fd-a85a-4083924c9b60'::uuid, 'b9791678-053f-5d74-84c2-44141cf740bd'::uuid, 'Lors de la contraction, les filaments d’actine se raccourcissent.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils GLISSENT le long des filaments de myosine : c’est le sarcomère qui raccourcit.', 3),
    ('a988a29b-ed1c-57cb-9b2b-59591a9accc1'::uuid, 'b9791678-053f-5d74-84c2-44141cf740bd'::uuid, 'Quel est le rôle de l’ATP dans le cycle des têtes de myosine ?', 'mcq', '["Sa fixation détache la tête de l’actine et son hydrolyse la réarme","Il libère le calcium du réticulum","Il déclenche le potentiel d’action","Il allonge le filament d’actine"]'::jsonb, 0, 'Sans ATP, les têtes restent accrochées : c’est la rigidité cadavérique.', 4),
    ('3c75290b-caaa-51dc-b430-2cb245eee00f'::uuid, 'b9791678-053f-5d74-84c2-44141cf740bd'::uuid, 'Quel ion libère les sites de fixation sur l’actine ?', 'mcq', '["Le calcium","Le sodium","Le potassium","Le chlorure"]'::jsonb, 0, 'Il déplace le complexe protéique qui masque ces sites au repos.', 5),
    ('114b354a-04a8-51f4-8a6e-cb7b1bf58844'::uuid, 'b9791678-053f-5d74-84c2-44141cf740bd'::uuid, 'Le réticulum sarcoplasmique est le réservoir interne de calcium de la fibre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il le libère à l’arrivée du signal et le repompe activement au relâchement.', 6),
    ('73dd8f6d-43b5-5912-9ad9-29bab018bb78'::uuid, 'b9791678-053f-5d74-84c2-44141cf740bd'::uuid, 'Qu’appelle-t-on unité motrice ?', 'mcq', '["Un motoneurone et l’ensemble des fibres qu’il innerve","Un sarcomère isolé","Une myofibrille entière","Un muscle et son tendon"]'::jsonb, 0, 'Elles se contractent toutes ensemble : quelques fibres pour l’œil, plus de mille pour le mollet.', 7),
    ('6394ec53-f7bb-5957-b136-2aec417f7dfa'::uuid, 'b9791678-053f-5d74-84c2-44141cf740bd'::uuid, 'De quoi dépend la force développée par un muscle ?', 'mcq', '["Du nombre d’unités motrices recrutées et de la fréquence des messages","De la longueur des filaments de myosine","Du nombre de noyaux par fibre","De la quantité de calcium disponible seule"]'::jsonb, 0, 'Le recrutement progressif permet de doser précisément l’effort.', 8),
    ('5eca6283-b47c-5597-b3b3-e500535630ca'::uuid, '847a6990-7f1d-5498-af11-998251f00fd8'::uuid, 'Combien de temps la réserve d’ATP d’une fibre musculaire permet-elle de tenir ?', 'mcq', '["2 à 3 secondes d’effort intense","Environ 2 minutes","Environ 10 minutes","Plusieurs heures"]'::jsonb, 0, 'D’où la nécessité de la régénérer en permanence par trois voies métaboliques.', 1),
    ('93e6539e-f8fb-53be-b826-09c49b301dd4'::uuid, '847a6990-7f1d-5498-af11-998251f00fd8'::uuid, 'Quelle voie est mobilisée en premier lors d’un sprint de 100 m ?', 'mcq', '["La phosphocréatine","La fermentation lactique","La respiration cellulaire","La dégradation des lipides"]'::jsonb, 0, 'Immédiate, sans oxygène, mais épuisée en une dizaine de secondes.', 2),
    ('4e24c264-1a5c-53cd-b2f2-04f14caeaeae'::uuid, '847a6990-7f1d-5498-af11-998251f00fd8'::uuid, 'Combien d’ATP la fermentation lactique produit-elle par molécule de glucose ?', 'mcq', '["2","18","36","100"]'::jsonb, 0, 'C’est peu, mais rapide et indépendant de l’apport en dioxygène.', 3),
    ('21784714-a873-5b48-848f-e2b94f83e431'::uuid, '847a6990-7f1d-5498-af11-998251f00fd8'::uuid, 'La fermentation lactique se déroule dans la mitochondrie.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle a lieu dans le CYTOPLASME : seule la respiration mobilise la mitochondrie.', 4),
    ('80c3dc0f-d725-5275-aee6-055d6deafb45'::uuid, '847a6990-7f1d-5498-af11-998251f00fd8'::uuid, 'Où se déroule le cycle de Krebs ?', 'mcq', '["Dans la matrice mitochondriale","Dans le cytoplasme","Sur la membrane plasmique","Dans le réticulum sarcoplasmique"]'::jsonb, 0, 'La chaîne respiratoire, elle, siège sur la membrane interne de la mitochondrie.', 5),
    ('52c59e1f-9b4e-5c2c-973d-8fccbf9c5c8d'::uuid, '847a6990-7f1d-5498-af11-998251f00fd8'::uuid, 'Quel est l’ordre de grandeur du rendement de la respiration cellulaire ?', 'mcq', '["30 à 36 ATP par glucose","2 ATP par glucose","4 ATP par glucose","200 ATP par glucose"]'::jsonb, 0, 'Une quinzaine de fois plus que la fermentation : c’est la voie de l’endurance.', 6),
    ('779c4a5f-b71d-5bb4-b3c7-69718f8be9ca'::uuid, '847a6990-7f1d-5498-af11-998251f00fd8'::uuid, 'Les trois voies de régénération de l’ATP fonctionnent simultanément.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est leur contribution RELATIVE qui change au cours de l’effort, pas leur activation.', 7),
    ('fe9593db-65f2-52f1-b04e-6187e4d8669a'::uuid, '847a6990-7f1d-5498-af11-998251f00fd8'::uuid, 'Qu’est-ce qui caractérise une fibre musculaire de type I ?', 'mcq', '["Riche en mitochondries, résistante à la fatigue","Pauvre en mitochondries, très puissante","Dépourvue de myoglobine","Incapable d’utiliser le dioxygène"]'::jsonb, 0, 'Ce sont les fibres lentes et rouges, celles du marathonien.', 8),
    ('24345294-40b3-568e-99e2-e6eb47b14226'::uuid, 'd322f19e-48af-5d33-ac7f-c891f9410f18'::uuid, 'Autour de quelle valeur la glycémie est-elle régulée ?', 'mcq', '["Environ 1 g/L","Environ 0,1 g/L","Environ 5 g/L","Environ 10 g/L"]'::jsonb, 0, 'Cette stabilité, à jeun comme après un repas, est un exemple d’homéostasie.', 1),
    ('63aa7aeb-41f1-5f1b-b642-d0188958cc19'::uuid, 'd322f19e-48af-5d33-ac7f-c891f9410f18'::uuid, 'Pourquoi le glycogène musculaire ne peut-il pas servir à toute la glycémie ?', 'mcq', '["La fibre musculaire ne peut pas relibérer de glucose dans le sang","Il est trop peu abondant","Il est dégradé trop lentement","Il est stocké sous forme de lipides"]'::jsonb, 0, 'Elle n’a pas l’enzyme nécessaire ; c’est le foie qui joue ce rôle.', 2),
    ('6b6542d2-f315-5726-8d82-2e5af71df009'::uuid, 'd322f19e-48af-5d33-ac7f-c891f9410f18'::uuid, 'Quelle est la seule hormone hypoglycémiante de l’organisme ?', 'mcq', '["L’insuline","Le glucagon","L’adrénaline","Le cortisol"]'::jsonb, 0, 'Elle est produite par les cellules β des îlots de Langerhans.', 3),
    ('053307d9-c066-5817-bac1-f95a20904ef2'::uuid, 'd322f19e-48af-5d33-ac7f-c891f9410f18'::uuid, 'Le glucagon est sécrété par les cellules α du pancréas quand la glycémie baisse.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il déclenche dans le foie l’hydrolyse du glycogène et la production de glucose.', 4),
    ('ad922901-3166-5017-97f3-b4d49952f3d4'::uuid, 'd322f19e-48af-5d33-ac7f-c891f9410f18'::uuid, 'Quel transporteur l’insuline fait-elle migrer vers la membrane des cellules musculaires ?', 'mcq', '["GLUT4","L’ATP synthase","La myosine","L’acétylcholine"]'::jsonb, 0, 'C’est ce qui permet l’entrée massive de glucose dans la cellule.', 5),
    ('583ff76f-6a0e-5317-b40a-3ed0949bac54'::uuid, 'd322f19e-48af-5d33-ac7f-c891f9410f18'::uuid, 'Quel organe est le principal effecteur de la régulation de la glycémie ?', 'mcq', '["Le foie","Le pancréas","Le muscle","Le rein"]'::jsonb, 0, 'Le pancréas est le capteur et l’émetteur ; le foie stocke et déstocke.', 6),
    ('33ef82ac-27fc-50b0-8c24-a7e2520d4485'::uuid, 'd322f19e-48af-5d33-ac7f-c891f9410f18'::uuid, 'Le diabète de type 1 résulte d’une destruction auto-immune des cellules β.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il n’y a alors plus d’insuline du tout : le traitement par insuline est vital.', 7),
    ('8892f632-2860-5174-bfbb-f777e82cfe0a'::uuid, 'd322f19e-48af-5d33-ac7f-c891f9410f18'::uuid, 'Qu’est-ce qui caractérise le diabète de type 2 ?', 'mcq', '["Une insulinorésistance des cellules cibles","Une absence totale d’insuline dès l’enfance","Un excès de glucagon d’origine génétique","Une destruction du foie"]'::jsonb, 0, 'L’insuline est présente mais inefficace ; le pancréas compense puis s’épuise.', 8),
    ('543f5330-275f-5c9a-a888-f56651ed1530'::uuid, 'f8028125-a14c-5599-b7b6-e9e5c486867f'::uuid, 'Quelle hormone est libérée par la médullosurrénale lors de la réponse rapide au stress ?', 'mcq', '["L’adrénaline","Le cortisol","L’insuline","La CRH"]'::jsonb, 0, 'Elle prépare l’organisme à l’action en quelques secondes.', 1),
    ('60ab0849-a410-57bc-bd5a-4b8ff3334683'::uuid, 'f8028125-a14c-5599-b7b6-e9e5c486867f'::uuid, 'Quels effets caractérisent la phase d’alarme ?', 'mcq', '["Hausse de la fréquence cardiaque, de la glycémie et de la vigilance","Ralentissement du cœur et somnolence","Baisse de la pression artérielle","Augmentation de la digestion"]'::jsonb, 0, 'C’est la réponse « combat ou fuite » décrite par Cannon.', 2),
    ('d15757bd-e086-5f6d-8a9b-c13f6dbf6b36'::uuid, 'f8028125-a14c-5599-b7b6-e9e5c486867f'::uuid, 'L’axe corticotrope met en jeu trois étages hormonaux successifs.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'CRH de l’hypothalamus, ACTH de l’hypophyse, cortisol de la corticosurrénale.', 3),
    ('6a9c0abb-4fd5-513b-9b69-acd75e08131a'::uuid, 'f8028125-a14c-5599-b7b6-e9e5c486867f'::uuid, 'Quelle hormone l’hypophyse libère-t-elle en réponse à la CRH ?', 'mcq', '["L’ACTH","Le cortisol","L’adrénaline","Le glucagon"]'::jsonb, 0, 'L’ACTH circule dans le sang et stimule la corticosurrénale.', 4),
    ('defade62-7b26-5e20-b801-91661f05566f'::uuid, 'f8028125-a14c-5599-b7b6-e9e5c486867f'::uuid, 'Quel est le rôle principal du cortisol dans la réponse au stress ?', 'mcq', '["Maintenir la disponibilité énergétique dans la durée","Accélérer le cœur en quelques secondes","Dilater les pupilles","Faire baisser la glycémie"]'::jsonb, 0, 'Il stimule la néoglucogenèse et mobilise les lipides.', 5),
    ('fea1a922-3bf7-52c5-b184-c5f70c293171'::uuid, 'f8028125-a14c-5599-b7b6-e9e5c486867f'::uuid, 'Le cortisol freine la sécrétion de CRH et d’ACTH.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est le rétrocontrôle négatif : le système s’auto-limite et redescend.', 6),
    ('ef83dff6-dc1b-5a84-8c77-a507e2fb33a2'::uuid, 'f8028125-a14c-5599-b7b6-e9e5c486867f'::uuid, 'Quelles sont les trois phases du syndrome général d’adaptation de Selye ?', 'mcq', '["Alarme, résistance, épuisement","Alerte, fuite, combat","Excitation, plateau, sommeil","Contraction, relâchement, repos"]'::jsonb, 0, 'Les deux premières sont bénéfiques ; le problème commence à la troisième.', 7),
    ('1e281a59-2fb5-5369-80f1-2f9908aecab5'::uuid, 'f8028125-a14c-5599-b7b6-e9e5c486867f'::uuid, 'De quoi dépend l’intensité de la réponse au stress d’une personne à l’autre ?', 'mcq', '["De son histoire, de son sentiment de contrôle et de son entourage","Uniquement de la gravité objective de l’événement","De sa masse musculaire","De sa glycémie initiale seule"]'::jsonb, 0, 'C’est l’ÉVALUATION de la situation qui compte, pas seulement la situation.', 8),
    ('efcb95b0-056c-58f8-bc74-861c554e92ef'::uuid, '50425102-a577-577b-9f9c-6060d877a496'::uuid, 'Que devient le rétrocontrôle négatif en cas de stress chronique ?', 'mcq', '["Il se désensibilise et le cortisol reste durablement élevé","Il devient plus efficace","Il disparaît immédiatement","Il est remplacé par un rétrocontrôle positif"]'::jsonb, 0, 'Les récepteurs au cortisol deviennent moins sensibles : le frein fonctionne mal.', 1),
    ('a0ad128f-5c71-5227-a3e7-cf1236faa99d'::uuid, '50425102-a577-577b-9f9c-6060d877a496'::uuid, 'Quelle structure cérébrale est particulièrement vulnérable au cortisol chronique ?', 'mcq', '["L’hippocampe","Le cortex moteur","Le cervelet","Le bulbe rachidien"]'::jsonb, 0, 'Riche en récepteurs au cortisol, il perd du volume, ce qui altère la mémoire.', 2),
    ('1c7e05b8-b1ed-5023-be11-9ff4f0e2fce0'::uuid, '50425102-a577-577b-9f9c-6060d877a496'::uuid, 'Un cortisol chroniquement élevé affaiblit les défenses immunitaires.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le cortisol est immunosuppresseur : infections plus fréquentes, cicatrisation retardée.', 3),
    ('9e08826c-043a-555f-9f3e-146d71c0b499'::uuid, '50425102-a577-577b-9f9c-6060d877a496'::uuid, 'Pourquoi l’atteinte de l’hippocampe aggrave-t-elle le stress chronique ?', 'mcq', '["Il participe au rétrocontrôle, que son atteinte affaiblit encore","Il produit l’adrénaline","Il contrôle la fréquence cardiaque","Il stocke le glycogène"]'::jsonb, 0, 'C’est un cercle vicieux : le cortisol abîme ce qui devait le freiner.', 4),
    ('f2868ad3-c5d5-5862-afcd-348ea0373c17'::uuid, '50425102-a577-577b-9f9c-6060d877a496'::uuid, 'Quelle conséquence métabolique le stress chronique favorise-t-il ?', 'mcq', '["Une résistance à l’insuline, terrain du diabète de type 2","Une hypoglycémie permanente","Une baisse du stockage des graisses","Une hausse de la masse musculaire"]'::jsonb, 0, 'Avec hyperglycémie chronique et stockage abdominal des graisses.', 5),
    ('022d9bc0-bc4a-5bc2-aae6-154c39ac24d1'::uuid, '50425102-a577-577b-9f9c-6060d877a496'::uuid, 'Le burn-out s’explique uniquement par une fragilité individuelle.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les facteurs organisationnels — charge, autonomie, reconnaissance — sont déterminants.', 6),
    ('ff920b49-c9bf-53d5-8455-472a84a4aafd'::uuid, '50425102-a577-577b-9f9c-6060d877a496'::uuid, 'Quelle combinaison est la plus délétère au travail ?', 'mcq', '["Forte exigence et faible latitude de décision","Faible exigence et forte autonomie","Forte exigence et forte autonomie","Faible exigence et faible autonomie"]'::jsonb, 0, 'Le sentiment de contrôle est le déterminant le mieux documenté.', 7),
    ('7eb19589-31ca-5f99-8c23-2a726f5dcf08'::uuid, '50425102-a577-577b-9f9c-6060d877a496'::uuid, 'Quel levier de résilience abaisse le niveau de cortisol de base ?', 'mcq', '["L’activité physique régulière","La privation de sommeil","L’isolement social","L’augmentation de la charge de travail"]'::jsonb, 0, 'Avec le sommeil, le soutien social et la régulation émotionnelle.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('svt');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('svt')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 233 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 233 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
